/*
 * A183121  Magnetic Tower of Hanoi, total number of moves, generated by a
 *          certain algorithm, yielding a "forward moving" non-optimal
 *          solution of the [RED ; NEUTRAL ; NEUTRAL] or [NEUTRAL ; NEUTRAL ;
 *          BLUE] pre-colored puzzle.
 * https://oeis.org/A183121
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) follows the recurrence * * a(0) = 0, a(1) = 1, a(2) = 4,
 *            a(3) = 11 * For n ≥ 4: * if n is even: a(n) = 3·a(n‑1) – n² + 6n
 *            – 11 * if n is odd : a(n) = 3·a(n‑1) – n² + 6n – 10 * * (The
 *            sequence is OEIS A183121 – Magnetic Tower of Hanoi, total number
 *            * of moves.)
 * Range:     u8 n <= 6, u16 n <= 11, u32 n <= 21, u64 n <= 41, u128 n <= 81,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of already computed values */
    static seq_t *cache   = NULL;
    static idx_t  cache_len = 0;    /* number of slots allocated (≥ cache_len) */

    /* --- ensure cache large enough to hold indices up to n --- */
    if (cache_len <= n) {
        idx_t new_len = n + 1;
        seq_t *new_cache = (seq_t *)malloc(new_len * sizeof(seq_t));
        for (idx_t i = 0; i < cache_len; ++i)           /* copy old data   */
            new_cache[i] = cache[i];
        free(cache);                                    /* free old array  */
        cache     = new_cache;
        cache_len = new_len;
    }

    /* --- initialise the fixed first four terms (if not done already) --- */
    if (cache_len > 0) {
        cache[0] = (seq_t)0;
        if (n >= 1) cache[1] = (seq_t)1;
        if (n >= 2) cache[2] = (seq_t)4;
        if (n >= 3) cache[3] = (seq_t)11;
    }

    /* --- compute missing terms up to n (respecting any out‑of‑order calls) --- */
    for (idx_t i = 4; i <= n; ++i) {
        if (cache[i] != (seq_t)0)            /* already computed          */
            continue;

        seq_t prev  = cache[i-1];
        seq_t term  = 3 * prev;              /* 3·a(i‑1)                  */
        term -= (seq_t)i * (seq_t)i;         /* – i²                       */
        term += 6 * (seq_t)i;                /* + 6i                       */
        term -= ((i & 1) == 0) ? (seq_t)11 : (seq_t)10;   /* –11 or –10 */

        cache[i] = term;
    }

    return cache[n];
}
